#include <cstdlib>
using namespace std;

typedef long long int int64;

int main() {
    int64 n, k;
    scanf("%lld%lld", &n, &k);

    vector<int64> h(n);
    for(int64 i = 0; i < n; i++)
        scanf("%lld", &h[i]);

    vector<int64> ans(n);
    ans[0] = 0;
    ans[1] = abs(h[1] - h[0]);

    for(int64 i = 2; i < n; i++) {
        ans[i] = abs(h[i] - h[i - 1]) + ans[i - 1];
        if (i > k) {
 ans[i] = min(ans[i], abs(h[i] - h[i - k]) + ans[i - k]);
        }
        for(int64 j = 2; j < k && j <= i; j++)
 ans[i] = min(ans[i], abs(h[i] - h[i - j]) + ans[i - j]);
    }
    printf("%lld\n", ans[n - 1]);
}

